def parse_args_and_kwargs(self, cmdline):
        """
        cmdline: list

        returns tuple of: args (list), kwargs (dict)
        """
        if isinstance(cmdline, str):
            cmdline = cmdline.split()
        args = []
        kwargs = {}
        for arg in cmdline:
            if '=' in arg:
                k, v = arg.split('=')
                kwargs[k] = v
            else:
                args.append(arg)
        return args, kwargs

